#include <stdio.h>
/* ex06：CSMA/CD 的最小帧长——为什么以太网帧不能太短
 * 冲突检测要求：发送方在「发完这一帧」之前必须能听到冲突。
 * 最坏情况是两个站相距最远，信号要跑一个来回（2τ）才互相听到。
 * 所以：帧的发送时延 >= 2τ  =>  最小帧长 = 速率 × 2τ
 * 10Mbps 以太网取 2τ = 51.2us，于是最小帧长 = 10M * 51.2us = 512 bit = 64 字节。
 * 小于 64 字节的帧（runt）会被视为冲突碎片丢弃。*/
int main(void) {
    double v = 2.0e8;                 /* 信号在电缆中约 2×10^8 m/s */
    struct { const char *name; double mbps; double min_frame_byte; } eth[] = {
        {"10BASE-T",   10.0,   64},
        {"100BASE-TX", 100.0,  64},
        {"1000BASE-T", 1000.0, 512}    /* 千兆用「载波扩展」把等效帧拉长到 512B */
    };

    printf("%-12s %-8s %-12s %-14s %s\n", "standard", "Mbps", "min_frame(B)", "t_frame(us)", "2tau(us)");
    printf("--------------------------------------------------------------\n");
    for (int i = 0; i < 3; i++) {
        double bits = eth[i].min_frame_byte * 8;
        double rate = eth[i].mbps * 1e6;
        double t_frame_us = bits / rate * 1e6;          /* us */
        /* 设计上让发送时延恰好等于争用期 2τ，所以两列数值相同 */
        printf("%-12s %-8.0f %-12.0f %-14.3f %.3f\n",
               eth[i].name, eth[i].mbps, eth[i].min_frame_byte, t_frame_us, t_frame_us);
    }
    printf("--------------------------------------------------------------\n");

    /* 纯传播意义上的最大距离（不含中继器/收发器延迟） */
    double t_frame_us = 64 * 8 / (10.0e6) * 1e6;        /* 51.2 us */
    double d_max = v * (t_frame_us * 1e-6) / 2.0;       /* 2τ 对应往返，故除 2 */
    printf("10Mbps 以太网：2tau = %.1f us，纯传播理论上限距离 = v*2tau/2 = %.0f m\n",
           t_frame_us, d_max);
    printf("但标准取 2500 m（10BASE5，最多 4 个中继器）：\n");
    printf("  因为 2tau 里除了电缆传播，还有中继器与收发器的处理延迟，\n");
    printf("  2500 m 往返只需 %.1f us，剩下 %.1f us 留给这些硬件延迟。\n",
           2 * 2500 / v * 1e6, t_frame_us - 2 * 2500 / v * 1e6);
    printf("\n结论：帧太短 -> 发完了还没听到冲突 -> 冲突漏检 -> 大量重传；\n");
    printf("      所以以太网规定最小帧 64 字节，不足的要填充（padding）。\n");
    return 0;
}
